	private static final class FailingFootprintFactory extends DefaultCollectionFactory {
		private int observations;
		private int clears;
		private int closes;

		@Override
		public OptionalLong getSpillFileBytes() {
			observations++;
			throw new UncheckedIOException(new IOException("unavailable spill file"));
		}

		@Override
		public <K, V> Map<K, V> createMap() {
			return new HashMap<>() {
				@Override
				public void clear() {
					clears++;
					super.clear();
				}
			};
		}

		@Override
		public void close() {
			closes++;
		}
	}

	private static final class ObservedMapDbFactory extends MapDb3CollectionFactory {
		private int closes;

		private ObservedMapDbFactory() {
			super(1);
		}

		private boolean spilled() {
			return db != null;
		}

		private long observedFileBytes() {
			long bytes = 0L;
			for (String file : db.getStore().getAllFiles()) {
				bytes += new File(file).length();
			}
			return bytes;
		}

		@Override
		public void close() {
			closes++;
			super.close();
		}
	}
